// Reads a Really Bad Chess board from a screenshot (ImageData), all in the browser.
//
// The game draws pieces in a flat style: ink is grey 34, white pieces are filled with pure white
// and have a white halo, black pieces have a light grey (238) halo. Board squares are grey 233
// with pure black hatching, or tinted when highlighted. So a piece's silhouette is the set of
// ink, white and halo pixels in a cell, and its colour is the share of ink in that silhouette.
// The silhouette, scaled to 32x32, is matched against one template per piece type.

export const N = 32;
const TYPES = 'pnbrqk';

function neutral(r, g, b) { return Math.abs(r - g) <= 3 && Math.abs(g - b) <= 3; }

// The board: the run of rows that are not the page background whose height is closest to the
// image width (the board is square and spans the screen width).
export function findBoard(img) {
  const { width: W, height: H, data } = img;
  const at = (x, y) => (y * W + x) * 4;
  const b0 = at(2, 2), bg = [data[b0], data[b0 + 1], data[b0 + 2]];
  const isBg = y => {
    let n = 0, m = 0;
    for (let x = 0; x < W; x += 4, m++) {
      const i = at(x, y);
      if (Math.abs(data[i] - bg[0]) + Math.abs(data[i + 1] - bg[1]) + Math.abs(data[i + 2] - bg[2]) < 8) n++;
    }
    return n / m > 0.97;
  };
  let best = null, y = 0;
  while (y < H) {
    while (y < H && isBg(y)) y++;
    const top = y;
    while (y < H && !isBg(y)) y++;
    const h = y - top;
    if (h > W * 0.5 && h < W * 1.25 && (!best || Math.abs(h - W) < Math.abs(best.size - W))) best = { top, size: h };
  }
  if (!best) return null;
  // the board may be narrower than the screen; take its width from the run's height
  return { top: best.top, left: (W - best.size) / 2, size: best.size };
}

// Silhouette of one cell as an N*N Float32Array (0..1), plus ink and white pixel counts.
export function cellMask(img, board, r, c) {
  const { width: W, height: H, data } = img;
  const s = board.size / 8;
  const x1 = board.left + c * s, y1 = board.top + r * s;
  const mask = new Float32Array(N * N);
  const cnt = new Float32Array(N * N);
  let ink = 0, white = 0, red = 0, total = 0;
  const y0 = Math.max(0, Math.floor(y1)), yEnd = Math.min(H, Math.ceil(y1 + s));
  const x0 = Math.max(0, Math.floor(x1)), xEnd = Math.min(W, Math.ceil(x1 + s));
  for (let y = y0; y < yEnd; y++) {
    const gy = Math.min(N - 1, Math.floor((y - y1) / s * N));
    if (gy < 0) continue;
    for (let x = x0; x < xEnd; x++) {
      const gx = Math.min(N - 1, Math.floor((x - x1) / s * N));
      if (gx < 0) continue;
      const i = (y * W + x) * 4, R = data[i], G = data[i + 1], B = data[i + 2];
      let v = 0;
      if (R > 200 && R - B > 50 && R - G > 50) red++;
      if (neutral(R, G, B)) {
        if (R >= 24 && R <= 46) { v = 1; ink++; }
        else if (R >= 250) { v = 1; white++; }
        else if (R >= 236 && R <= 241) v = 1;
      }
      mask[gy * N + gx] += v;
      cnt[gy * N + gx]++;
      total++;
    }
  }
  for (let k = 0; k < N * N; k++) mask[k] = cnt[k] ? mask[k] / cnt[k] : 0;
  return { mask, ink: ink / total, white: white / total, red: red / total };
}

// templates: { p: Float32Array(N*N), n: ..., ... }
export function classify(cell, templates) {
  let area = 0;
  for (const v of cell.mask) area += v;
  area /= N * N;
  if (area < 0.08 || cell.ink < 0.04) return { piece: '.', score: 1 - area, area };
  let best = null, second = null;
  for (const t of TYPES) {
    const tm = templates[t];
    let inter = 0, uni = 0;
    for (let k = 0; k < N * N; k++) { inter += Math.min(cell.mask[k], tm[k]); uni += Math.max(cell.mask[k], tm[k]); }
    const iou = inter / uni;
    if (!best || iou > best.iou) { second = best; best = { t, iou }; } else if (!second || iou > second.iou) second = { t, iou };
  }
  const black = cell.ink > cell.white;
  return { piece: black ? best.t : best.t.toUpperCase(), score: best.iou, margin: best.iou - second.iou, area };
}

export function readBoard(img, templates = TEMPLATES) {
  const board = findBoard(img);
  if (!board) return null;
  const cells = [];
  const reds = [];
  for (let r = 0; r < 8; r++) for (let c = 0; c < 8; c++) {
    const m = cellMask(img, board, r, c);
    if (m.red > 0.2) reds.push(r * 8 + c);
    cells.push(classify(m, templates));
  }
  const squares = cells.map(c => c.piece).join('');
  // The game tints the engine's last move red: the emptied square is where it came from.
  let last = null;
  if (reds.length === 2) {
    const [a, b] = reds, ea = squares[a] === '.', eb = squares[b] === '.';
    if (ea !== eb) last = ea ? { f: a, t: b } : { f: b, t: a };
  }
  return { board, squares, cells, last };
}

// Templates: the average silhouette of each piece type, cut from real screenshots, N*N digits 0-9.
const RAW = {"p": "", "n": "", "b": "", "r": "", "q": "", "k": ""};
export const TEMPLATES = Object.fromEntries([...TYPES].map(t => [t, Float32Array.from(RAW[t], ch => +ch / 9)]));
